cat > /tmp/binlog-analyzer/Analyzer/Program.cs << 'CSHARP'
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

Console.WriteLine("=== BUILD RESULT ===");
Console.WriteLine($"Succeeded: {build.Succeeded}");
Console.WriteLine();

// Collect all errors
var errors = new List<(string project, string file, int line, int col, string code, string msg, string subcategory)>();
var warnings = new List<(string project, string file, int line, int col, string code, string msg)>();

build.VisitAllChildren<Error>(e => {
    var proj = "";
    var parent = e.Parent;
    while (parent != null) {
        if (parent is Project p) { proj = p.Name; break; }
        parent = (parent as TreeNode)?.Parent as BaseNode;
    }
    errors.Add((proj, e.File ?? "", e.LineNumber, e.ColumnNumber, e.Code ?? "", e.Text ?? "", e.Subcategory ?? ""));
});

build.VisitAllChildren<Warning>(w => {
    var proj = "";
    var parent = w.Parent;
    while (parent != null) {
        if (parent is Project p) { proj = p.Name; break; }
        parent = (parent as TreeNode)?.Parent as BaseNode;
    }
    warnings.Add((proj, w.File ?? "", w.LineNumber, w.ColumnNumber, w.Code ?? "", w.Text ?? ""));
});

// Group errors by project
Console.WriteLine("=== ERRORS ===");
foreach (var g in errors.GroupBy(e => e.project).OrderBy(g => g.Key)) {
    Console.WriteLine($"\n--- Project: {g.Key} ---");
    foreach (var e in g) {
        Console.WriteLine($"  [{e.code}] {e.file}({e.line},{e.col}): {e.msg}");
    }
}

Console.WriteLine($"\n=== SUMMARY: {errors.Count} error(s), {warnings.Count} warning(s) ===");

// Show relevant warnings too
if (warnings.Any(w => w.code.StartsWith("NU") || w.code.StartsWith("MSB"))) {
    Console.WriteLine("\n=== RELEVANT WARNINGS (NuGet/MSBuild) ===");
    foreach (var w in warnings.Where(w => w.code.StartsWith("NU") || w.code.StartsWith("MSB"))) {
        Console.WriteLine($"  [{w.code}] {w.project}: {w.msg}");
    }
}

// List all projects and their build status
Console.WriteLine("\n=== PROJECT BUILD STATUS ===");
build.VisitAllChildren<Project>(p => {
    // skip inner builds
    if (p.Name != null) {
        Console.WriteLine($"  {p.Name} -> Succeeded: {p.Succeeded}");
    }
});
