cat > /tmp/binlog-analyzer/Analyzer/Program.cs << 'CSHARP'
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Check for any MSB errors, failed targets, etc.
Console.WriteLine("=== SEARCHING FOR ALL DIAGNOSTICS ===");

build.VisitAllChildren<AbstractDiagnostic>(d => {
    var proj = "";
    var current = (BaseNode)d;
    while (current != null) {
        if (current is Project p) { proj = p.Name ?? ""; break; }
        current = (current as TreeNode)?.Parent;
    }
    var kind = d is Error ? "ERROR" : d is Warning ? "WARN" : "INFO";
    Console.WriteLine($"  [{kind}] [{d.Code}] Project={proj} File={d.File}({d.LineNumber},{d.ColumnNumber}): {d.Text}");
});

// Check project references to understand dependency chain
Console.WriteLine("\n=== PROJECT REFERENCES (from items) ===");
var seen = new HashSet<string>();
build.VisitAllChildren<Item>(item => {
    if (item.Name == "ProjectReference") {
        var proj = "";
        var current = (BaseNode)item;
        while (current != null) {
            if (current is Project p) { proj = p.Name ?? ""; break; }
            current = (current as TreeNode)?.Parent;
        }
        var key = $"{proj} -> {item.Text}";
        if (seen.Add(key))
            Console.WriteLine($"  {key}");
    }
});

// Check for MSB4181 or other build infrastructure errors
Console.WriteLine("\n=== MESSAGES WITH 'error' or 'fail' ===");
build.VisitAllChildren<Message>(m => {
    if (m.Text != null && (m.Text.Contains("error", StringComparison.OrdinalIgnoreCase) 
        || m.Text.Contains("fail", StringComparison.OrdinalIgnoreCase))
        && !m.Text.Contains("ErrorReport")
        && !m.Text.Contains("error.cs")
        && m.Text.Length < 200) {
        var proj = "";
        var current = (BaseNode)m;
        while (current != null) {
            if (current is Project p) { proj = p.Name ?? ""; break; }
            current = (current as TreeNode)?.Parent;
        }
        Console.WriteLine($"  [{proj}] {m.Text}");
    }
});
