Console.WriteLine("\n=== CSC COMMAND LINES ===");
build.VisitAllChildren<Task>(t => {
    if (t.Name == "Csc") {
        var proj = "";
        var current = (BaseNode)t;
        while (current != null) {
            if (current is Project p) { proj = p.Name ?? ""; break; }
            current = (current as TreeNode)?.Parent;
        }
        Console.WriteLine($"\n  Project: {proj}");
        // Look at command line args
        foreach (var child in t.Children) {
            if (child is Property prop) {
                if (prop.Name == "Sources" || prop.Name == "References" || prop.Name == "CommandLineArguments") {
                    Console.WriteLine($"    {prop.Name}: {prop.Value}");
                }
            }
            if (child is Folder f && f.Name == "Parameters") {
                foreach (var p2 in f.Children) {
                    if (p2 is Property pp && (pp.Name == "Sources" || pp.Name == "References")) {
                        Console.WriteLine($"    {pp.Name}: {pp.Value}");
                    }
                }
            }
        }
    }
});

