            if (current is Project p) { proj = p.Name ?? ""; break; }
            current = (current as TreeNode)?.Parent;
        }
        foreach (var child in ai.Children.OfType<Item>()) {
            var key = $"{proj}: {child.Text}";
            if (seenPkg.Add(key))
